<script setup lang="ts">import {computed} from 'vue';import {Run} from '../types/domain';import {median,number,probability} from '../utils/format';const props=defineProps<{run:Run}>();const diff=computed(()=>{const d=props.run.result.bootstrap?.median_difference;return d?.interval?number(d.interval[0],0)+' – '+number(d.interval[1],0)+' h':null});</script><template><div class="run-summary"><div v-for="(g,i) in run.result.groups" :key="g.cohort.id" :class="['group-summary','group-'+i]"><span>{{g.cohort.code}} / {{g.cohort.process}}</span><h3>{{g.cohort.name}}</h3><b>{{median(g.median)}}</b><small>中位耐久 · {{g.events}} 事件 / {{g.censored}} 删失</small></div><div class="test-summary"><span>LOG-RANK / 双侧</span><b>{{probability(run.result.logrank.p_value)}}</b><small>{{run.result.logrank.estimable?'p 值 · 非因果结论':'无可比较事件或方差为零'}}</small></div><div v-if="diff&&run.result.bootstrap" class="test-summary boot-summary"><span>整卷重抽样 · 中位时长差</span><b>{{diff}}</b><small>有效重复 {{run.result.bootstrap.median_difference.valid}} / {{run.result.bootstrap.replicates}} · 种子 {{run.result.bootstrap.seed}}</small></div></div></template>
